{
  "name": "电子秤后端抽象模块",
  "name_en": "Abstract Scale Backend",
  "manufacturer": "",
  "description": "用于实验室电子秤集成的非物理软件组件，定义清零、去皮和读取重量等通用控制接口，供上层实验自动化系统与具体电子秤实现对接。",
  "description_en": "A non-physical software component for laboratory scale integration. It defines common control interfaces such as zeroing, taring, and reading weight, allowing higher-level lab automation software to interact with concrete scale implementations.",
  "actions": [
    {
      "action_name": "auto-zero",
      "description": "向已连接的电子秤发送清零指令。",
      "description_en": "Send a zero command to the connected scale."
    },
    {
      "action_name": "auto-tare",
      "description": "向已连接的电子秤发送去皮指令。",
      "description_en": "Send a tare command to the connected scale."
    },
    {
      "action_name": "auto-read_weight",
      "description": "读取电子秤当前重量，单位为克。",
      "description_en": "Read the current weight from the scale in grams."
    },
    {
      "action_name": "auto-get_weight",
      "description": "通过兼容旧接口读取电子秤当前重量，单位为克。",
      "description_en": "Read the current weight from the scale in grams through a deprecated compatibility method."
    }
  ],
  "tag_hints": [
    "scale integration",
    "weighing",
    "tare",
    "zeroing",
    "weight readout",
    "lab automation"
  ]
}

